    _RTQ_LOGGER.setLevel(_logging.DEBUG)
    try:
        _with_switch(switch, lambda: _rtq(_RTQ_LOGGER, attempt=attempt, diagnosis=_pair(stage, reason, shape)))
    finally:
        _RTQ_LOGGER.removeHandler(sink)
    return any(
        level == 'WARNING' and 'event=batch_recovery outcome=held reason=awaiting_fenced_recovery' in message
        for level, message in sink.records
    )


